"""One-off helper used while the initial migration is still being iterated on (pre-release).

Adds the pg_trgm extension and the trigram index for news title search to the autogenerated
initial migration. Safe to run repeatedly.
"""
import pathlib
import sys

path = pathlib.Path(sys.argv[1])
s = path.read_text()
if "pg_trgm" in s:
    sys.exit(0)
s = s.replace('''def upgrade() -> None:
    # ### commands auto generated by Alembic - please adjust! ###''', '''def upgrade() -> None:
    op.execute("CREATE EXTENSION IF NOT EXISTS pg_trgm")
    # ### commands auto generated by Alembic - please adjust! ###''', 1)
idx = s.index("def downgrade() -> None:")
up, down = s[:idx], s[idx:]
up = up.rstrip() + '''
    # Fuzzy title search for the news feed (Market News module)
    op.execute("CREATE INDEX IF NOT EXISTS ix_news_articles_title_trgm ON news_articles USING gin (title gin_trgm_ops)")


'''
down = down.replace('''def downgrade() -> None:
    # ### commands auto generated by Alembic - please adjust! ###''', '''def downgrade() -> None:
    op.execute("DROP INDEX IF EXISTS ix_news_articles_title_trgm")
    # ### commands auto generated by Alembic - please adjust! ###''', 1)
path.write_text(up + down)
print("patched", path.name)
